"""Deterministic build order for a dependency graph. See task.md."""

from __future__ import annotations


class CycleError(ValueError):
    """Raised when the graph contains a cycle.

    `.cycle` names the members of the reported cycle, in depends-on order,
    without repeating the first member at the end.
    """

    def __init__(self, cycle: list[str]) -> None:
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = list(cycle)


def resolve(graph: dict[str, list[str]]) -> list[str]:
    """Return the build order of `graph`, dependencies first."""
    import heapq
    from collections import deque

    deps: dict[str, set[str]] = {}
    for node, ds in graph.items():
        deps.setdefault(node, set()).update(ds)
        for d in ds:
            deps.setdefault(d, set())

    dependents: dict[str, list[str]] = {n: [] for n in deps}
    pending = {n: len(ds) for n, ds in deps.items()}
    for n, ds in deps.items():
        for d in ds:
            dependents[d].append(n)

    heap = [n for n, c in pending.items() if c == 0]
    heapq.heapify(heap)
    order: list[str] = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in dependents[n]:
            pending[m] -= 1
            if pending[m] == 0:
                heapq.heappush(heap, m)

    if len(order) == len(deps):
        return order

    emitted = set(order)
    nodes = [n for n in deps if n not in emitted]
    best: list[str] | None = None
    for s in sorted(nodes):
        # dist[v]: fewest dependency edges from v back to s, using nodes >= s
        dist = {s: 0}
        queue = deque([s])
        while queue:
            v = queue.popleft()
            for u in dependents[v]:
                if u >= s and u not in emitted and u not in dist:
                    dist[u] = dist[v] + 1
                    queue.append(u)
        length = None
        for d in deps[s]:
            if d in dist:
                cand = dist[d] + 1
                if length is None or cand < length:
                    length = cand
        if length is None or (best is not None and length > len(best)):
            continue
        cycle = [s]
        cur = s
        for i in range(1, length):
            cur = min(d for d in deps[cur] if d > s and dist.get(d) == length - i)
            cycle.append(cur)
        if best is None or (len(cycle), cycle) < (len(best), best):
            best = cycle
    assert best is not None
    raise CycleError(best)
